class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0) in the grid
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final (row, col) position to the grid position
        # position = row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store color counts for each player
        player_color_count = {}

        # Process each pick
        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            # Find the maximum count of any single color for this player
            max_count = 0
            if player in player_color_count:
                for color, count in player_color_count[player].items():
                    max_count = max(max_count, count)

            # Player i wins if they have at least i+1 balls of the same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            for k in range(m // 2):
                if grid[k][j] != grid[m - 1 - k][j]:
                    cols_flips += 1

        # Return minimum of the two options
        return min(rows_flips, cols_flips)

