class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1

        # Build adjacency list
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def simulate(start_node):
            # times[i] = time when node i gets marked
            times = [-1] * n
            times[start_node] = 0

            # BFS to propagate marking
            queue = deque([start_node])

            while queue:
                node = queue.popleft()

                # For each unmarked neighbor, check if it can be marked
                for neighbor in graph[node]:
                    if times[neighbor] != -1:
                        continue

                    # Determine the marking time based on parity
                    if neighbor % 2 == 1:  # odd node - needs neighbor marked at time-1
                        # Check if any of node's neighbors was marked at time-1
                        # Actually, we need to check if at least one adjacent node to neighbor 
                        # was marked at time-1
                        can_mark = False
                        for adj in graph[neighbor]:
                            if times[adj] == times[node] - 1:
                                can_mark = True
                                break
                        if can_mark:
                            times[neighbor] = times[node] + 1
                            queue.append(neighbor)

                    else:  # even node - needs neighbor marked at time-2
                        can_mark = False
                        for adj in graph[neighbor]:
                            if times[adj] == times[node] - 2:
                                can_mark = True
                                break
                        if can_mark:
                            times[neighbor] = times[node] + 1
                            queue.append(neighbor)

            return max(times)

        result = []
        for i in range(n):
            result.append(simulate(i))

        return result

