                    if neighbor % 2 == 1:  # odd node - needs neighbor marked at time-1
                        # Can mark at current_time + 1 if any neighbor of neighbor was marked at current_time
                        can_mark = False
                        for adj in graph[neighbor]:
                            if times[adj] == current_time:
                                can_mark = True
                                break
                        if can_mark:
                            times[neighbor] = current_time + 1
                            queue.append(neighbor)

                    else:  # even node - needs neighbor marked at time-2
                        # Can mark at current_time + 1 if any neighbor of neighbor was marked at current_time - 1
                        can_mark = False
                        for adj in graph[neighbor]:
                            if times[adj] == current_time - 1:
                                can_mark = True
                                break
                        if can_mark:
                            times[neighbor] = current_time + 1
                            queue.append(neighbor)

            return max(times)

        result = []
        for i in range(n):
            result.append(simulate(i))

        return result

