N, D = map(int, input().split())
points = []
for _ in range(N):
    x, y = map(int, input().split())
    points.append((x, y))

if D == 0:
    # Only possible if N=1 and we're at the point
    if N == 1:
        print(1)
    else:
        print(0)
else:
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]

    # Find reasonable range
    min_x = min(xs) - D
    max_x = max(xs) + D
    min_y = min(ys) - D
    max_y = max(ys) + D

    # Precompute cost for each x
    x_costs = {}
    for x in range(min_x, max_x + 1):
        cost_x = sum(abs(x - xi) for xi in xs)
        x_costs[x] = cost_x

    # Precompute cost for each y
    y_costs = {}
    for y in range(min_y, max_y + 1):
        cost_y = sum(abs(y - yi) for yi in ys)
        y_costs[y] = cost_y

    # Count valid pairs
    count = 0
    for x in x_costs:
        if x_costs[x] > D:
            continue
        remaining = D - x_costs[x]
        for y in y_costs:
            if y_costs[y] <= remaining:
                count += 1

    print(count)

